-- ============================================================
-- ADAM BRAIN SEED V3 — MAXIMUM INTELLIGENCE
-- Every domain Adam needs to be world-class
-- ============================================================
BEGIN;

-- ── SCHEMA ADDITIONS ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS due_diligence_items (
  id SERIAL PRIMARY KEY,
  category TEXT NOT NULL,
  item TEXT NOT NULL,
  priority TEXT DEFAULT 'high',
  when_to_check TEXT,
  how_to_check TEXT,
  red_flag_indicators TEXT,
  deal_types TEXT[],
  notes TEXT
);

CREATE TABLE IF NOT EXISTS scope_templates (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  scope_level TEXT NOT NULL,
  property_type TEXT DEFAULT 'SFR',
  sqft_min INTEGER,
  sqft_max INTEGER,
  arv_min INTEGER,
  arv_max INTEGER,
  line_items JSONB NOT NULL,
  total_low INTEGER,
  total_mid INTEGER,
  total_high INTEGER,
  timeline_weeks_low INTEGER,
  timeline_weeks_high INTEGER,
  notes TEXT
);

CREATE TABLE IF NOT EXISTS contractor_knowledge (
  id SERIAL PRIMARY KEY,
  trade TEXT NOT NULL,
  vetting_questions TEXT[],
  red_flags TEXT[],
  green_flags TEXT[],
  typical_rate TEXT,
  payment_terms TEXT,
  contract_requirements TEXT,
  common_issues TEXT,
  tampa_bay_notes TEXT
);

CREATE TABLE IF NOT EXISTS deal_structures (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  when_to_use TEXT,
  how_it_works TEXT,
  advantages TEXT[],
  disadvantages TEXT[],
  legal_requirements TEXT,
  risk_level TEXT,
  ccg_applicability TEXT,
  example_scenario TEXT
);

CREATE TABLE IF NOT EXISTS market_benchmarks (
  id SERIAL PRIMARY KEY,
  metric_name TEXT NOT NULL,
  category TEXT NOT NULL,
  strong_value TEXT,
  acceptable_value TEXT,
  weak_value TEXT,
  unit TEXT,
  calculation TEXT,
  notes TEXT,
  applies_to TEXT[]
);

CREATE TABLE IF NOT EXISTS competitor_profiles (
  id SERIAL PRIMARY KEY,
  name TEXT,
  type TEXT,
  primary_markets TEXT[],
  typical_buy_criteria TEXT,
  close_speed TEXT,
  reputation TEXT,
  competitive_notes TEXT,
  known_since DATE DEFAULT CURRENT_DATE
);


-- ── DUE DILIGENCE MASTER CHECKLIST ───────────────────────────
INSERT INTO due_diligence_items (category, item, priority, when_to_check, how_to_check, red_flag_indicators, deal_types, notes) VALUES

-- TITLE / LEGAL
('title','Pull title search from title company','critical','Before making offer if time permits, definitely before closing','Order title commitment from investor-friendly title company. Cost: $150-300.','Any Schedule B-I requirements that cannot be cleared. Multiple judgment liens.',ARRAY['flip','brrrr','rental','wholesale'],'Title commitment reveals all liens, encumbrances, easements. Read Schedule B-I carefully — these are things that must be resolved before closing.'),
('title','Check code enforcement violations at municipality','critical','Before making offer','Go to city/county code enforcement department website. Search by address. Call if online search unavailable.','Open code violations with significant daily accrued fines. Unpermitted structures.',ARRAY['flip','brrrr','rental','wholesale'],'Not all code violations appear in title search. Must check directly with municipality. Hillsborough: hillsboroughcounty.org. Pasco: pascocountyfl.net'),
('title','Pull permit history at county building department','critical','Before making offer','Search county building department portal by address.','Open permits from prior work. Unpermitted additions. Permitted work that failed final inspection.',ARRAY['flip','brrrr','rental','wholesale'],'Unpermitted square footage cannot be included in MLS listing and does not count toward appraisal.'),
('title','Check HOA status and restrictions','high','Before making offer','Ask seller/wholesaler directly. Then verify with HOA management company. Request HOA estoppel letter.','Rental restrictions. Special assessments. Litigation. Violations on property.',ARRAY['brrrr','rental'],'HOA rental restrictions can completely kill a rental or BRRRR deal. Verify before offering on any property with HOA.'),
('title','Verify property boundaries with survey','medium','After contract, before closing','Order survey. Cost $600-1,200 for boundary survey.','Encroachments (neighbor fence on your property or vice versa). Unexpected easements. Boundary discrepancies.',ARRAY['flip','brrrr','rental'],'Survey is especially important on: corner lots, properties with additions, wooded lots, any boundary dispute history.'),
('title','Check for IRS/federal tax liens','critical','Title search reveals these','Title search should catch federal liens. Verify separately if any question.','Any federal lien attached to property. These survive sale.','ARRAY[''flip'',''brrrr'',''rental'',''wholesale'']','Federal tax liens are serious — lender will require payoff. May delay or kill closing.'),
('title','Research utility easements and rights of way','medium','Review survey and title commitment','Look at survey for easement notations. Check utility company records.','Large utility easements limiting buildable area. Drainage easements through yard.','ARRAY[''flip'',''brrrr'',''rental'']','Most utility easements are standard and acceptable. Flag only if they significantly limit use or improvement.'),
('title','Verify property is in correct flood zone','high','Before making offer','FEMA flood map: msc.fema.gov. Check FIRM panel for exact flood zone.','Zone AE or VE designation on property in purchase criteria.','ARRAY[''flip'',''brrrr'',''rental'',''wholesale'']','Even a partial AE zone designation may require flood insurance. Budget $2,000-8,000/yr if required.'),

-- PROPERTY CONDITION
('condition','Get full home inspection by licensed inspector','critical','Immediately after contract','Hire Florida-licensed home inspector. Cost $400-600. Be present during inspection.','Major structural issues, roof failure, electrical hazards, plumbing failures, mold, foundation concerns.',ARRAY['flip','brrrr','rental'],'Inspector cannot see behind walls but notes visible symptoms of hidden problems. Use inspection report to negotiate price reduction or repair credits.'),
('condition','Get WDO (termite) inspection','critical','Same time as home inspection','Hire Florida-licensed pest control company for WDO (Wood Destroying Organisms) report. Cost $75-150.','Active termite infestation. Significant structural damage from prior infestation.',ARRAY['flip','brrrr','rental'],'WDO report required by most lenders. Required disclosure when reselling. Active termites = negotiate treatment and damage repair into price.'),
('condition','Get four-point inspection for insurance','high','Before or immediately after closing','Licensed inspector or home inspector performs. Cost $150-250.','Failed four-point on roof, HVAC, plumbing, or electrical.','ARRAY[''brrrr'',''rental'']','Failed four-point = difficulty getting insurance. Know this before closing. Can use as negotiating tool.'),
('condition','Check roof age and condition','critical','Before making offer via wholesaler inquiry, confirm at inspection','Ask wholesaler for age. Verify at inspection with inspection report. Check permit history for re-roofing permits.','Roof over 20 years old without recent inspection/repair. Missing shingles. Active leaks. Improper installation.',ARRAY['flip','brrrr','rental','wholesale'],'Roof age is the #1 insurance factor in Florida. Roof over 15 years = budget replacement or face major insurance challenges.'),
('condition','Inspect HVAC system thoroughly','critical','At inspection','Run system for 15 minutes. Check all registers for airflow. Inspect unit for age and condition.','System over 12-15 years old. R-22 refrigerant (obsolete). Rusted coils. Poor airflow to rooms.',ARRAY['flip','brrrr','rental'],'Florida HVAC runs year-round = shorter lifespan. Budget $9,000-12,000 for replacement if needed.'),
('condition','Check electrical panel brand and condition','critical','At inspection','Inspect panel brand. Note age and capacity. Check for aluminum wiring.','Federal Pacific Stab-Lok panel. Zinsco panel. Double-tapped breakers. Fuse box instead of breakers. Aluminum wiring.',ARRAY['flip','brrrr','rental'],'Federal Pacific and Zinsco panels are safety hazards and uninsurable. Budget panel replacement if found.'),
('condition','Test all plumbing fixtures and look for leaks','high','At inspection','Run all faucets, flush all toilets, run dishwasher if present. Check under all sinks.','Galvanized or polybutylene (gray plastic) supply pipes. Active leaks. Low water pressure. Slow drains.',ARRAY['flip','brrrr','rental'],'Polybutylene pipes (gray, 1978-1995) = automatic re-pipe budget. Galvanized pipes = corrosion, failure risk.'),
('condition','Test all appliances','medium','At inspection','Run all appliances: dishwasher, oven/range, refrigerator, garbage disposal, microwave.','Non-functional appliances on rentals. Missing appliances on flips affecting ARV.',ARRAY['flip','rental','brrrr'],'Include appliance replacement in scope for flips. Rentals need functional appliances minimum.'),
('condition','Check for signs of water intrusion and mold','critical','At inspection - check attic, under sinks, around windows and doors','Look for staining, musty smell, soft drywall, discolored flooring. Check attic for roof leaks.','Black or green mold visible. Extensive water staining. Musty smell throughout home.',ARRAY['flip','brrrr','rental','wholesale'],'Mold must be disclosed when reselling. Remediation required. Budget $2,000-25,000+ depending on extent.'),
('condition','Evaluate foundation and slab condition','critical','At inspection','Look for major cracks (>1/4 inch), sticking doors/windows, uneven floors. Check with structural engineer if concerned.','Stair-step cracking in block walls. Active floor heaving. Doors/windows consistently sticking. Slab moisture.',ARRAY['flip','brrrr','rental'],'Sinkhole activity causes foundation movement. Get structural engineer ($400-700) if ANY concerns. Never buy obvious sinkhole without massive discount.'),
('condition','Check pool condition if present','high','At inspection','Inspect pool structure, equipment, and safety barrier.','Cracked pool shell. Non-functional equipment. Missing safety barrier (code violation).',ARRAY['flip','brrrr','rental'],'FL law requires pool safety barrier. Budget replacement if missing. Pool equipment: $2,000-4,500 to replace.'),
('condition','Inspect septic system if on septic','critical','Before closing on Hernando/rural properties','Hire septic inspector for pump, inspect, dye test. Cost $250-400.','Failed dye test (drain field failure). Tank damage. Tree root intrusion.',ARRAY['flip','brrrr','rental'],'Failed drain field = $8,000-20,000 replacement. Non-negotiable deal point if failed. Budget accordingly or walk.'),
('condition','Test well water quality if on well','high','Before closing on well properties','Water quality test from lab. Test for bacteria, nitrates, hardness, iron, pH. Cost $100-300.','Bacteria present. Nitrates above EPA limits. Heavy iron or sulfur.',ARRAY['flip','brrrr','rental'],'Failed bacteria test = health issue, must disclose. Treatment system $400-3,000. Some lenders require potable water certification.'),

-- FINANCIAL VERIFICATION
('financial','Verify asking price against recent comps','critical','Before making offer','Pull 3-5 comparable sales within 1 mile, last 90 days, similar specs. Use Urban AI.','Asking price within 5% of ARV (no margin). Wholesaler comps are all investor-to-investor sales.',ARRAY['flip','brrrr','rental','wholesale'],'Never trust wholesaler ARV without independent verification. Urban AI is specifically built to counter wholesaler ARV inflation.'),
('financial','Calculate total all-in cost with conservative assumptions','critical','Before offering','Include: purchase + rehab (add 15% contingency) + holding costs (6 months) + financing + selling costs (7.5%).','Total all-in within 10% of ARV (insufficient margin). Rehab estimate based on quick walk-through only.',ARRAY['flip','wholesale'],'Always run all-in analysis with conservative numbers. If deal only works at optimistic assumptions, it is not a deal.'),
('financial','Verify rental income with current leases and market data','critical','Before offering on occupied deals','Get copies of all leases. Pull HUD FMR for area. Check Zillow/Apartments.com for comparable rentals.','Below-market leases that cannot be adjusted quickly. Tenants with strong statutory protections.',ARRAY['brrrr','rental'],'Actual signed leases are the ground truth. Market rent matters for refinance appraisal on BRRRR but lease rate matters for current cash flow.'),
('financial','Get contractor estimates before closing if possible','high','During due diligence period','Have trusted contractor walk property. Get itemized estimate.','Major scope surprises found by contractor that wholesaler or inspector missed. Estimates 30%+ above budget.',ARRAY['flip','brrrr'],'Inspection period exists for exactly this. Use time to get real contractor numbers. If numbers change, renegotiate or walk.'),
('financial','Verify property tax with county appraiser','high','Before closing','Check county property appraiser website for assessed value and tax history.','Assessed value significantly above purchase price (tax bill will be high). Special assessment charges.',ARRAY['brrrr','rental'],'Property taxes reset at purchase price for non-homestead properties in FL. Plan for higher tax bill than prior owner paid.'),
('financial','Calculate BRRRR refinance math precisely','critical','Before making offer on BRRRR deals','Run: ARV x 75% = refi amount. Compare to total cash in. Calculate cash flow post-refi.','Cash left in exceeds 25% of total investment. Negative cash flow after refi.','ARRAY[''brrrr'']','BRRRR only makes sense if refi returns sufficient capital. Model conservatively on ARV.'),

-- MARKET / EXIT
('market','Verify retail buyer demand with recent comparable sales','critical','Before making offer','Check Redfin for recent sales. Are they to retail buyers or investors? Days on market? List to sale ratio?','Area showing only investor-to-investor sales. Days on market over 45 days for comparable homes. Multiple price reductions on recent listings.',ARRAY['flip','wholesale'],'Flip exit requires retail buyers. Investor-dominated market = longer hold time and lower sale price. Price this risk into your offer.'),
('market','Identify exit strategy before making offer','high','Before making offer','Determine: flip, rental, BRRRR, or wholesale. Confirm market supports chosen exit.','No clear viable exit. Market does not support intended use.','ARRAY[''flip'',''brrrr'',''rental'',''wholesale'']','Every deal needs a clear exit before you commit. Never buy without knowing how you will sell or refinance.'),
('market','Research any planned development or zoning changes','medium','Before closing','Check county planning department. Ask local real estate attorney. Review local news.','Planned highway expansion through neighborhood. Zoning change that would reduce residential appeal.',ARRAY['flip','brrrr','rental'],'Large infrastructure projects can dramatically affect property values positively or negatively. Know what is planned.'),
('market','Check days on market trend for comparable homes','high','Before making offer','Pull MLS data or Redfin for 90-day DOM average on comparable homes.','DOM trending up significantly. Multiple listings sitting over 60 days.','ARRAY[''flip'']','Rising DOM = softening buyer demand. Build this into hold time assumption. More months of interest = less profit.');


-- ── SCOPE OF WORK TEMPLATES ───────────────────────────────────
INSERT INTO scope_templates (name, scope_level, sqft_min, sqft_max, arv_min, arv_max, line_items, total_low, total_mid, total_high, timeline_weeks_low, timeline_weeks_high, notes) VALUES
('Light Cosmetic Flip — Sub $250K ARV', 'LIGHT', 900, 1400, 150000, 260000,
  '{"roof_repair": 2000, "hvac_service": 800, "paint_interior": 3500, "paint_exterior": 2500, "flooring_lvp": 3500, "kitchen_cosmetic": 6500, "bathrooms_cosmetic": 5000, "fixtures_hardware": 1200, "landscaping_basic": 1500, "pressure_wash": 400, "cleaning": 600, "permits_misc": 1000, "contingency": 2800}'::JSONB,
  28000, 38000, 50000, 6, 10,
  'Target profile: 3/2, 1000-1400 sqft, 1985-2000 CBS, Pasco/Hernando. Kitchen gets paint + hardware + countertops only. Bathrooms get vanity + toilet + fixtures. No structural work. Goal: make it clean, functional, attractive to first-time buyers in $200-250K range.'),

('Medium Flip — $250K-350K ARV', 'MEDIUM', 1200, 1800, 250000, 360000,
  '{"roof_replace": 13000, "hvac_replace": 10000, "paint_interior": 4500, "paint_exterior": 3500, "flooring_lvp": 5500, "kitchen_medium": 16000, "bathrooms_medium": 10000, "electrical_panel": 2800, "plumbing_repairs": 2000, "windows_standard": 5000, "doors_exterior": 2000, "garage_door": 1800, "landscaping_refresh": 3000, "driveway_seal": 800, "fixtures_hardware": 2000, "appliances": 3500, "permits": 2500, "contingency": 7000}'::JSONB,
  82000, 108000, 135000, 10, 16,
  'Target profile: 3/2, 1200-1800 sqft, 1985-1999 CBS, Hillsborough/Wesley Chapel. New roof and HVAC. Updated kitchen and baths. New flooring throughout. Updated electrical and basic plumbing. Goal: compete with new construction in $280-350K market.'),

('Heavy Renovation — $350K-500K ARV', 'FULL', 1500, 2500, 350000, 510000,
  '{"roof_replace": 15000, "hvac_replace": 12000, "paint_interior": 6000, "paint_exterior": 5000, "flooring_lvp_tile": 9000, "kitchen_full": 28000, "bathrooms_full": 18000, "electrical_rewire_panel": 12000, "plumbing_partial": 6000, "windows_impact": 18000, "doors_impact_front": 3000, "garage_door": 2500, "landscaping_full": 7000, "driveway_new": 4500, "smart_home_ev": 3000, "fixtures_hardware": 3500, "appliances_premium": 5000, "permits": 4000, "contingency": 14000}'::JSONB,
  162000, 212000, 265000, 14, 22,
  'Target profile: 4/2+, 1600-2500 sqft, 1990-2010, premium Pasco or South Hillsborough. Everything new. Premium finishes. Impact windows. Smart home features. EV prep. Quartz countertops. Goal: compete with builder-grade new construction in $400K+ market.'),

('BRRRR Light Rehab — Rentable Only', 'LIGHT', 1000, 1600, 200000, 310000,
  '{"hvac_service_or_repair": 2500, "roof_repair_only": 3000, "paint_interior": 3000, "flooring_lvp_main": 2800, "kitchen_minimal": 3500, "bathrooms_minimal": 3000, "appliances_basic": 2000, "cleaning_deep": 600, "landscaping_basic": 1000, "miscellaneous": 1500, "contingency": 2600}'::JSONB,
  22000, 30000, 42000, 4, 7,
  'BRRRR rehab goal: make it rentable, not retail-ready. Paint, LVP flooring in main areas, functional kitchen and baths, working appliances. Do NOT install quartz countertops or premium finishes. Tenant will not pay more rent for quartz countertops but you spent $4,000. Minimize cash in so BRRRR math works.'),

('Rental Turn — Occupied to Vacant Refresh', 'LIGHT', 900, 1600, 0, 0,
  '{"paint_interior_walls": 2000, "flooring_carpet_bedrooms": 1200, "flooring_lvp_main": 1500, "cleaning_deep": 600, "appliances_replace_as_needed": 1500, "plumbing_fixes": 500, "electrical_fixes": 500, "blinds_curtain_rods": 400, "landscaping_basic": 800, "miscellaneous_repairs": 1000}'::JSONB,
  8000, 12000, 18000, 2, 4,
  'Between-tenant turn. Goal: refresh without major capital expenditure. Light paint, replace most worn flooring, deep clean, address any deferred maintenance. Budget $10,000-15,000 typical for 3/2 turn. Plan for 2-4 weeks vacancy.');

-- ── CONTRACTOR KNOWLEDGE BASE ─────────────────────────────────
INSERT INTO contractor_knowledge (trade, vetting_questions, red_flags, green_flags, typical_rate, payment_terms, contract_requirements, common_issues, tampa_bay_notes) VALUES
('General Contractor', 
  ARRAY['Are you licensed in Florida? (License lookup: myfloridalicense.com)', 'How many active projects are you running?', 'Can you provide 3 recent investor references?', 'Do you use licensed subcontractors for electrical and plumbing?', 'What is your draw schedule?', 'Can you start within 2 weeks?'],
  ARRAY['Cannot provide license number', 'Wants >30% upfront before starting', 'Cannot provide references from investors', 'Uses unlicensed subs for licensed trades', 'Evasive about insurance (workers comp + liability)', 'Cannot provide itemized written estimate'],
  ARRAY['Licensed and insured with verifiable records', 'Can provide 3+ investor references who will take your call', 'Itemized written estimate within 48 hours', 'Dedicated foreman on site daily', 'Clear communication on timeline and draw schedule', 'Experience with flip specifically (not just custom builds)'],
  '$45-65/hr labor for finish trades, $65-95/hr for specialty. GC markup: 10-20% on subs.',
  '10% at signing for materials only. Draw schedule based on completion milestones (rough-in, drywall, finish, final). NEVER pay ahead of work completed.',
  'Written scope of work with line items. Payment schedule tied to milestones. Lien waiver upon each draw payment. Right to substitute licensed subs. Completion date with penalty clause.',
  'Change orders inflate projects. Lock in scope before starting. Any additions must be written and priced before execution. "While we are in there" conversations are expensive.',
  'Tampa Bay has strong GC market but good ones stay busy. Build relationships before you need them. Cheaper GC often means corners cut — your buyers will find problems. Reference investors you know for quality GC referrals.'),

('Roofing Contractor',
  ARRAY['Florida roofing license number?', 'Do you pull permits?', 'What type of underlayment — peel and stick or felt?', 'What manufacturer are you using (CertainTeed, GAF, Owens Corning)?', 'Do you do decking replacement?', 'Can you provide manufacturer warranty?'],
  ARRAY['Does not pull permits', 'Uses felt underlayment when peel-and-stick is code in area', 'Cheapest bid by more than 20%', 'No references from recent jobs in same area', 'Cannot provide manufacturer warranty paperwork', 'Wants full payment upfront'],
  ARRAY['Pulls all permits', 'Uses peel-and-stick where required by code', 'Provides manufacturer warranty registered to property', 'Provides 5-year workmanship warranty', 'Can show recent jobs in neighborhood', 'Decking inspection included in estimate'],
  '$350-600 per roofing square (100 sqft) installed all-in. Average 3/2 home: 20-25 squares = $8,000-15,000.',
  '30% deposit, 40% when tear-off complete, 30% on completion and final inspection.',
  'Written scope with decking replacement price per sheet. Drip edge and flashing included. Underlayment specification. Permit included. Dumpster included.',
  'Roof insurance supplement games are common in FL. Do not get involved with assignment of benefits (AOB) — legal complexity. Full replacement preferred over repairs unless roof is recent.',
  'Post-hurricane, roofing contractors book up 6-12 months. Maintain relationships with 2-3 roofers. Some insurers require Owens Corning or GAF Duration shingles — verify before specifying.'),

('HVAC Contractor',
  ARRAY['Florida HVAC license number?', 'What brands do you install?', 'Do you pull permits?', 'Do you include ductwork inspection?', 'What warranty on new unit?', 'Can you service as well as install?'],
  ARRAY['Does not pull permits', 'Installs generic/unknown brands', 'Cannot explain SEER rating', 'Does not include ductwork assessment', 'No manufacturer warranty registration'],
  ARRAY['Pulls permits on new installs', 'Installs Carrier, Trane, Lennox, or Rheem', '10-year parts warranty registered to property', 'Ductwork assessment included', 'Can explain efficiency and sizing logic', '24/7 emergency service'],
  '$9,000-14,000 for new 3-ton central system installed with permit. Service: $85-150/hr.',
  '50% at equipment delivery, 50% on completion and passed inspection.',
  'Equipment model and SEER rating specified. Ductwork inspection included. Permit included. Thermostat included. Old equipment disposal included.',
  'Improperly sized units are expensive mistake. 3-ton is most common for 1,200-1,800 sqft homes. 4-ton for 1,800-2,500 sqft. Oversizing causes short-cycling.',
  'Variable speed units are worth the premium on rentals (quieter, better humidity control = fewer tenant complaints). Basic units for low-end flips.'),

('Plumbing Contractor',
  ARRAY['Florida plumbing license?', 'Do you do re-pipes?', 'What pipe material do you use?', 'Do you pull permits for re-pipes?', 'Can you do gas and water?', 'Water heater brands you install?'],
  ARRAY['No license', 'Recommends polybutylene replacement without acknowledging full scope', 'Excessive cost for basic jobs', 'Does not pull permits for re-pipe', 'Cannot answer questions about pipe materials used by decade'],
  ARRAY['Licensed', 'Transparent about scope and options', 'Pulls permits on all re-pipe work', 'Uses PEX-A (Wirsbo/Uponor) for re-pipes', 'Provides leak-free guarantee on re-pipe', 'Can do whole-home inspection'],
  'Re-pipe: $4,500-10,000 depending on size. Service: $125-200/hr.',
  '50% at start, 50% on completion.',
  'Pipe material specified. Permit included in re-pipe scope. Drywall patching after re-pipe: separate line item. Water heater brand and size specified.',
  'Slab leaks are common in older FL homes. Under-slab re-route can be done without breaking slab using epoxy lining or rerouting through attic. Get multiple opinions if slab work suggested.',
  'In Hernando and rural Pasco: many plumbers do both plumbing and well/septic work. Valuable to have one contractor who can handle both.'),

('Electrical Contractor',
  ARRAY['Florida electrical license?', 'Do you pull permits?', 'Experience with Federal Pacific or Zinsco panel replacement?', 'Can you assess aluminum wiring?', 'Do you do outdoor/pool electrical?', 'Experience with whole-home rewire?'],
  ARRAY['No license', 'Does not pull permits', 'Cannot assess aluminum wiring', 'Wants to use aluminum wiring for service entrance extensions', 'No experience with older FL electrical systems'],
  ARRAY['Licensed EC (Electrical Contractor)', 'Pulls all permits', 'Experience with FPE/Zinsco replacement', 'Can identify and assess aluminum wiring', 'Provides AFCI/GFCI upgrade quote', 'Experience with smart home wiring'],
  'Panel upgrade: $2,500-4,500. Rewire: $10,000-20,000. Service: $100-175/hr.',
  '30% start, 40% rough-in complete, 30% finish and passed inspection.',
  'Panel brand and amperage specified. GFCI locations included. Permit included. Smoke detector/CO detector included in scope.',
  'Aluminum wiring is not a death sentence — COPALUM or AlumiConn pigtailing is an approved solution cheaper than full rewire. Get electrician who knows this.','In new construction heavy areas, many electricians busy. Maintain relationships. REI groups have recommendations.'),

('General Paint Contractor',
  ARRAY['Can you do interior and exterior?', 'What paint brands do you use?', 'Do you do drywall repair?', 'Can you remove popcorn ceilings?', 'What does your crew size look like?', 'Typical timeline for 3/2?'],
  ARRAY['Extremely low bid — quality likely to suffer', 'Cannot do drywall repair separately', 'Uses cheap paint brands', 'Cannot do exterior stucco prep properly', 'No experience with Florida elastomeric for exterior'],
  ARRAY['Uses Sherwin-Williams or Benjamin Moore', 'Can do minor drywall repair', 'Crew of 3+ for efficiency', 'Can complete 3/2 interior in 3-4 days', 'Uses elastomeric for stucco exterior', 'Provides paint color recommendations for resale'],
  'Interior 3/2: $3,000-5,000. Exterior: $3,500-7,000. Popcorn removal: $1.50-3.00/sqft.',
  '30% start, 70% on completion.',
  'Paint brand and finish specified. Two coats included. Drywall patching included (minor). Ceiling painted separately specified.',
  'Good painter is the easiest $10K you spend on a flip — the visual transformation is massive. Do not scrimp here.',
  'Sherwin-Williams Emerald for walls (better coverage, worth premium). Benjamin Moore Aura is also excellent. For exterior stucco: Sherwin-Williams Elastomeric is appropriate.'),

('Flooring Contractor',
  ARRAY['Do you do LVP installation?', 'Can you remove existing flooring?', 'Do you do subfloor prep and leveling?', 'What brands do you carry?', 'Do you do tile as well?', 'Can you complete 1,400 sqft in 3 days?'],
  ARRAY['Cannot do subfloor prep', 'Wants to install over existing without inspection', 'Only does carpet', 'Uses low-quality LVP', 'Cannot complete efficiently — 1 person operation'],
  ARRAY['Does LVP and tile', 'Does subfloor prep and leveling', 'Can complete 1,200 sqft in 2-3 days', 'Carries quality LVP brands (Shaw, LifeProof, CoreTec)', 'Does transitions and molding'],
  'LVP install: $2-4/sqft. Tile install: $4-8/sqft. Old floor removal: $0.75-1.50/sqft.',
  '30% materials, 70% on completion.',
  'LVP brand and mm thickness specified. Old flooring removal included. Subfloor inspection included. Transitions included.',
  'Flooring contractor timing is critical — must be done after paint and before cabinets go in. Schedule accordingly.',
  'LifeProof (Home Depot) and Shaw are reliable brands. 6mm+ for rental grade. 8mm+ for flip. Waterproof core required in FL.');

-- ── DEAL STRUCTURES REFERENCE ─────────────────────────────────
INSERT INTO deal_structures (name, description, when_to_use, how_it_works, advantages, disadvantages, legal_requirements, risk_level, ccg_applicability, example_scenario) VALUES
('Straight Assignment',
  'CCG contracts to buy property then assigns the contract to an end buyer for an assignment fee.',
  'When CCG can get price low enough to add assignment fee and still be attractive to flipper/landlord buyer. When seller and wholesaler know about and allow assignment.',
  'CCG signs PSA with assignment clause allowed. CCG finds end buyer. CCG assigns its contractual rights to end buyer for assignment fee. End buyer closes directly with seller. CCG never takes title.',
  ARRAY['No title costs', 'No double closing costs', 'Simple and fast', 'No capital needed'],
  ARRAY['Discloses CCG purchase price to end buyer', 'Some sellers refuse assignment', 'Assignment fee visible in transaction'],
  'Assignment clause must be in original contract. Florida allows assignment unless prohibited.',
  'low',
  'primary for wholesale exits',
  'CCG contracts 123 Main St at $150K with $5K EMD. Assigns to flipper buyer for $165K. CCG collects $15K assignment fee at closing. Flipper pays $165K to seller directly.'),

('Double Close (A-B / B-C)',
  'CCG purchases property in A-to-B transaction then immediately sells in B-to-C transaction on same day.',
  'When CCG needs to conceal purchase price from end buyer. When assignment fee is very large (>$25K). When original contract prohibits assignment. When using transactional funding.',
  'CCG closes A-B purchase using transactional funding or own capital. Immediately closes B-C sale with end buyer. Two separate closings, two sets of title insurance. Net: CCG collects spread.',
  ARRAY['Hides purchase price', 'Works when assignment not allowed', 'Looks like normal purchase to seller'],
  ARRAY['Double closing costs ($2,000-5,000 extra)', 'Transactional funding fees if used', 'Some title companies will not do it', 'More complex'],
  'Need title company comfortable with simultaneous closes. May need transactional lender for A-B portion.',
  'medium',
  'secondary for wholesale when spread is large or assignment prohibited',
  'CCG contracts 456 Oak at $140K (prohibited from assignment). Secures buyer at $170K. Double closes: A-B at $140K with transactional funds, B-C at $170K. CCG nets $28K minus $3K costs = $25K.'),

('Novation Agreement',
  'CCG steps into a deal between a seller and a buyer (often a motivated seller with existing listing agreement or buyer agreement) to facilitate a transaction by modifying the original deal.',
  'When seller has existing mortgage they cannot satisfy through normal sale. When deal needs creative structure to work. When value can be created through proper deal structure.',
  'The original deal terms are replaced (novated) with new terms that work for all parties. Legal contracts are modified with all party consent. CCG gets compensated for deal creation.',
  ARRAY['Works in complex situations', 'Can unlock deals others cannot do', 'Significant compensation possible'],
  ARRAY['More complex legal structure', 'Requires real estate attorney', 'All parties must agree'],
  'Requires real estate attorney. All parties must consent. Written novation agreement required.',
  'high',
  'case by case — consult attorney. CCG does these but with counsel.',
  'Seller owes $200K, house worth $210K, cannot pay realtor commissions. Buyer exists but deal is stuck. CCG steps in, restructures deal, collects $10K fee.'),

('Sub-To (Subject-To Existing Mortgage)',
  'Buying a property with the seller''s existing mortgage staying in place. Buyer takes title, makes payments on seller''s loan.',
  'When seller has very low interest rate worth keeping. When seller cannot sell conventionally (underwater or upside down). When speed matters and seller needs out fast.',
  'Deed transfers to buyer. Seller''s mortgage stays in their name. Buyer makes payments to lender. Lender may not know (due-on-sale clause risk). Seller releases property, buyer controls it.',
  ARRAY['No new financing needed', 'Keep low interest rate', 'Can help underwater sellers', 'Fast close possible'],
  ARRAY['Due-on-sale clause risk (lender can call loan)', 'Seller still on hook if buyer defaults', 'Complex trust and documentation needed', 'Difficult to refinance out'],
  'Consult real estate attorney. Use land trust. Proper disclosure to seller. Insurance in buyer name.',
  'high',
  'occasional — not primary strategy. Consult attorney before every sub-to.',
  'Seller has 2.75% mortgage from 2021. House worth $280K, owes $220K. Seller relocating. CCG takes subject-to: gets house at 2.75% rate, seller freed from burden, CCG rents or flips.'),

('Seller Financing (Purchase Money Mortgage)',
  'Seller acts as the bank. Buyer pays seller directly over time rather than through a bank.',
  'When seller has no mortgage and needs income stream more than lump sum. When seller is avoiding capital gains through installment sale. When buyer cannot get conventional financing.',
  'Seller and buyer agree on purchase price, down payment, interest rate, and term. Seller holds note and mortgage. Buyer makes payments to seller. Seller retains lien until paid off.',
  ARRAY['Flexible terms negotiable', 'May get lower interest rate', 'No bank qualifying', 'Seller gets income stream', 'Installment sale tax treatment for seller'],
  ARRAY['Seller must be willing and financially positioned to wait', 'Must find right situation', 'More complex than cash purchase', 'Buyer default risk for seller'],
  'Promissory note and mortgage executed. Recorded with county. Proper title work.',
  'low',
  'occasional — good for rental acquisitions when seller wants income',
  'Seller owns $180K home free and clear. Needs monthly income. CCG pays $15K down, seller finances $165K at 6% for 10 years. Monthly payment $1,833 to seller. CCG rents property at $1,800, levers equity over time.'),

('Lease Option (Option to Purchase)',
  'CCG leases property with an option to purchase at a set price within a set time.',
  'When property needs time to appreciate to reach CCG''s ARV target. When seller is not ready to sell but will be. When option premium is low.',
  'CCG pays option consideration (typically $1,000-5,000). Pays rent during option period. Has right but not obligation to purchase at agreed price before option expires.',
  ARRAY['Controls property without buying', 'Lower capital required initially', 'Built-in purchase price', 'Can assign option in some cases'],
  ARRAY['Monthly rent outflow', 'Loses option premium if not exercised', 'Complex agreement', 'Seller may complicate exercise'],
  'Option agreement must be in writing. Recorded to protect option. Specific exercise procedure documented.',
  'medium',
  'occasional — niche strategy for specific situations',
  'Seller wants $285K for property CCG values at $260K today. Agrees to lease-option: CCG pays $2K option fee, $1,500/mo rent for 18 months, option to buy at $280K. After rehab of similar comps, market catches up and CCG exercises.'),

('Probate Purchase',
  'Purchasing property from a deceased person''s estate through the probate process.',
  'When property has died and heirs want to liquidate. When deal can be structured to work with PR (Personal Representative) and court timeline.',
  'PR (estate administrator) is authorized to sell with court approval. PR often prefers cash sale to avoid realtor commissions and delay. CCG makes offer, PR accepts, court approves, close.',
  ARRAY['Less competition than MLS', 'Motivated sellers (heirs want cash)', 'Often below market', 'PR appreciates speed and simplicity'],
  ARRAY['Timeline unpredictable (6-18 months)', 'Court approval adds steps', 'PR must price near market with fiduciary duty', 'Multiple heirs may disagree'],
  'PR must have Letters of Administration. Court must approve sale. Clean title required — may have liens.',
  'medium',
  'growing priority — excellent off-market source',
  'Owner died, left home to 3 adult children. None want to deal with it. PR accepts $210K cash offer from CCG vs $230K list price. Court approves 30 days later. CCG closes, rehabs, sells for $295K.');

-- ── MARKET BENCHMARKS TABLE ───────────────────────────────────
INSERT INTO market_benchmarks (metric_name, category, strong_value, acceptable_value, weak_value, unit, calculation, notes, applies_to) VALUES
('Profit Margin','flip','20%+ of ARV','12-20% of ARV','Below 12% of ARV','%','(Sale Price - All Costs) / ARV','CCG minimum: 10% of ARV or $30K, whichever is higher. Strong deals are 15%+.',ARRAY['flip']),
('Cash-on-Cash Return','rental','12%+ annually','8-12% annually','Below 8% annually','%','Annual Cash Flow / Cash Invested','Measure of return on actual equity deployed. Factor in all cash (down payment + closing costs + any rehab).',ARRAY['rental','brrrr']),
('DSCR Ratio','rental','1.25x+','1.0-1.25x','Below 1.0x','ratio','Monthly NOI / Monthly Debt Payment','1.25x is lender preferred. 1.0x is breakeven. Below 1.0x = negative cash flow.',ARRAY['rental','brrrr']),
('Cap Rate','rental','7%+ in CCG markets','5-7%','Below 5%','%','Annual NOI / Property Value','In Tampa Bay: 5-6% is current market cap rate. Only buy below 5% if strong appreciation play.',ARRAY['rental','brrrr']),
('Cash Left In (BRRRR)','brrrr','$0 or negative','1-20% of total invested','Over 25% of total invested','%','(Total Cash In - Refi Proceeds) / Total Cash In','Goal is to get all cash back through refinance. Below 20% = strong BRRRR. Negative = exceptional.',ARRAY['brrrr']),
('Days on Market','flip','Under 21 days','21-45 days','Over 45 days','days','Days from list date to under contract','Fast DOM means strong buyer demand. Slow DOM = price correction likely needed or market softening.',ARRAY['flip']),
('Assignment Fee','wholesale','$20,000-30,000+','$12,000-20,000','Under $10,000','dollars','(Assignment Price) - (CCG Purchase Price)','Under $10K is not worth the deal admin. Target $15K+ minimum. $20K+ is a strong wholesale deal.',ARRAY['wholesale']),
('ARV to Purchase Ratio','flip','65% or less','65-75%','Over 75% (without seller discount)','%','Purchase Price / ARV','The lower CCG pays relative to ARV, the more margin. Under 65% = great. 70%+ = tight.',ARRAY['flip','wholesale']),
('Gross Rent Multiplier','rental','Under 120x monthly','120-150x monthly','Over 150x monthly','x','Purchase Price / Monthly Gross Rent','Example: $200K purchase / $1,600 rent = 125x GRM. Lower is better — means lower price relative to income.',ARRAY['rental','brrrr']),
('Rehab Budget to ARV','flip','Under 15%','15-25%','Over 25%','%','Rehab Budget / ARV','Heavy rehab projects are higher risk. Under 15% rehab/ARV = lower execution risk. Over 25% = careful.',ARRAY['flip','brrrr']),
('Hold Time','flip','Under 4 months','4-6 months','Over 6 months','months','Time from purchase to sold and closed','Every extra month = $1,500-2,500 more in holding costs (interest, taxes, insurance, utilities).',ARRAY['flip']),
('Profit Per Month Held','flip','Over $8,000/month','$5,000-8,000/month','Under $5,000/month','$/month','Net Profit / Hold Months','Measures efficiency of capital. $50K profit over 5 months = $10K/month. $50K over 10 months = $5K/month.',ARRAY['flip']),
('List to Sale Ratio','flip/market','97-100%','94-97%','Below 93%','%','Sale Price / List Price','High ratio = strong market, sellers getting asking price. Low ratio = soft market, expect price reductions.',ARRAY['flip','wholesale']),
('Loan to Value at Purchase','flip','Under 70% all-in','70-80% all-in','Over 80% all-in','%','Total All-In Cost / ARV','Total all-in (purchase + rehab + costs) vs ARV. Under 70% = strong deal. Over 80% = thin margin.',ARRAY['flip','brrrr']);

-- ── COMPETITOR PROFILES (TAMPA BAY) ──────────────────────────
INSERT INTO competitor_profiles (name, type, primary_markets, typical_buy_criteria, close_speed, reputation, competitive_notes) VALUES
('Opendoor', 'iBuyer', ARRAY['Hillsborough','Pasco','Pinellas'], 'Pays 93-97% of market value minus fees (6-10% total). SFR, 1920-2020, $100K-$600K. Makes offer in 24-48 hours.', '30-60 days', 'Pays more than typical investors but less than retail. Easy process for sellers.', 'Not a direct competitor for wholesale/distressed. Competes when seller thinks about CCG vs Opendoor. CCG can beat on price for right deals. Opendoor is slower (60 days) vs CCG (7-14 days).'),
('Offerpad', 'iBuyer', ARRAY['Hillsborough','Pinellas'], 'Similar to Opendoor. Slightly more flexible on property condition.', '30-60 days', 'Smaller than Opendoor but similar model.', 'Same competitive dynamic as Opendoor. Not major concern for off-market distressed deals.'),
('HomeVestors / We Buy Ugly Houses', 'National franchise investor', ARRAY['Hillsborough','Pasco','Pinellas'], 'Buys deeply distressed at 50-65% ARV. Frame and CBS.', '7-14 days', 'National brand recognition with sellers. Known for below-market offers.', 'Competes for same motivated seller profile as CCG direct mail. Good brand recognition helps them get leads.'),
('Invitation Homes', 'Institutional SFR', ARRAY['Hillsborough','Pasco','Pinellas','Polk'], 'Buys vacant SFR for rental. Generally pays at or slightly below market. Not buying distressed typically.', '14-21 days', 'Large institutional — professional operations.', 'Not major competitor for wholesale. Could be buyer for CCG flips if they sell to retail buyers in their footprint.'),
('Amherst Residential', 'Institutional SFR', ARRAY['Hillsborough','Pasco'], 'Similar to Invitation Homes. Buys for SFR rental portfolio.', '14-21 days', 'Strong institutional operations.', 'Potential end buyer for CCG wholesale deals. Build relationship with their acquisition team.'),
('Local Volume Flipper (typical)', 'Active local investor', ARRAY['Pasco','Hillsborough','Hernando'], '70% ARV minus repairs. Prefers concrete block. 3/2+.', '7-14 days (cash)', 'Varies. Some very reputable, some reputation for retrading.', 'These are the buyers for CCG''s wholesale deals AND our competition for the same deals. Faster response time than most. Know them by name in each market.'),
('Out-of-State Remote Investor', 'Remote investor', ARRAY['Pasco','Hillsborough'], 'Often pays slightly over local MAO due to less market knowledge. Buys for rental or turn-key flip.', 'Often 21-30 days (HML)', 'Variable. Can be good buyers at slightly better prices for CCG wholesale.', 'Good wholesale buyers — pay slightly more because they lack local market knowledge. Build relationships with CA, NY, NJ investors buying in Tampa Bay.');


-- ── MASSIVE MARKET KNOWLEDGE EXPANSION V3 ─────────────────────
INSERT INTO market_knowledge (topic, category, subcategory, content, key_numbers, action_implications, source, confidence, applies_to_deal_types, tags) VALUES

-- HYPER-LOCAL MARKET INTELLIGENCE
('Pasco County: Zephyrhills 33525 Deep Dive','market_dynamics','micro_market','Zephyrhills (33525) is one of CCG primary target markets. Key characteristics: Median price $255K (2025). Predominantly CBS construction from 1985-1998. Strong migration from Hillsborough County overflow. Growing retail buyer demand from Tampa commuters (40 min to Brandon). Good schools — Pasco County schools system above average. Low crime relative to price point. Deal flow: steady from regional wholesalers. Competition: medium — not as saturated as Wesley Chapel. Rental demand: strong from essential workers, healthcare, warehouse/logistics employees (Amazon, FedEx distribution nearby).','Median sale: $255K. Average rent 3BR: $1,750. Days on market: 22. HUD FMR 3BR: $2,300. YoY appreciation: 8.5%.','Focus outreach here. Good BRRRR math at current prices. CBS 1988-1996 homes in Zephyrhills are the exact CCG target profile. When Urban scores HOT in 33525: prioritize immediately.',NULL,'high',ARRAY['flip','brrrr','rental'],ARRAY['33525','zephyrhills','pasco','micro_market']),

('Hillsborough County: Ruskin/SCC Deep Dive','market_dynamics','micro_market','Ruskin (33570) and Sun City Center (33573) in south Hillsborough are underrated CCG markets. Ruskin: growing bedroom community for Tampa workers. Significant industrial employment (distribution, warehousing) creates strong blue-collar rental demand. CBS homes from 1985-2005 plentiful at good price points. Median $295K. Less competition than north Hillsborough. Sun City Center: age-restricted (55+) — rental strategy limited but flip exits to active adults strong. Different buyer profile — plan exit before buying.',NULL,'Consider Ruskin as primary south Hillsborough focus. Good price point for BRRRR. Strong rental demand from Manatee County spillover workers. Flag SCC deals separately — buyer pool is 55+ only.',NULL,'high',ARRAY['flip','brrrr'],ARRAY['33570','ruskin','sun_city_center','hillsborough','micro_market']),

('Spring Hill (Hernando) Rental Market','market_dynamics','micro_market','Spring Hill is the BRRRR sweet spot of CCG territory. Lower prices ($230-260K), reasonable rents ($1,650-1,750/3BR), CBS construction from 1980-1998 dominant. Key factors: 1) Many retirees/near-retirees on fixed income — great long-term tenants. 2) Growing remote worker population from Tampa. 3) Less investor competition than Pasco. 4) Healthcare employment nearby (HCA hospitals, medical offices). 5) Walmart, Home Depot, local retail = employment base. Key risk: many septic systems (budget $300/yr pumping), some flood zones near Weeki Wachee River.','Median: $240K. Rent 3BR: $1,700. DSCR at 6.75%, 75% LTV on $240K ARV: $1,247/mo payment. NOI at $1,700 rent less expenses: approximately $950. Cash flow positive after DSCR.','Run BRRRR math on every Spring Hill deal. If CBU 1982-1995 CBS at under $185K — strongly consider BRRRR. Septic inspection budget: $350. Water treatment if well: $1,500 allowance.',NULL,'high',ARRAY['brrrr','rental'],ARRAY['34606','34608','34609','spring_hill','hernando','brrrr','rental']),

('Wesley Chapel Growth Zone','market_dynamics','micro_market','Wesley Chapel (33544, 33545) is Pasco County premium market. Massive new construction (Lennar, Pulte, DR Horton) driving population growth. Excellent schools (Wiregrass Ranch HS, Cypress Creek MS). Major retail (Wiregrass Mall, KRATE market). Strong corporate employment draw. Flip exits are very strong — retail buyers eager. BUT: high prices ($340-390K) compress margins. New construction competition is intense. Investor saturation higher than core Pasco. BRRRR math challenging at current price points.','Median: $370K. New construction: 1,500+ units per year permitted. School rating: 8-9/10. Days on market: 16-19.','In Wesley Chapel: only buy flips at very sharp price (below 60% ARV all-in). BRRRR math is hard unless significant discount. Better to find deals in surrounding areas and sell the finished product to Wesley Chapel buyers.',NULL,'high',ARRAY['flip'],ARRAY['33544','33545','wesley_chapel','pasco','premium_market']),

-- FLORIDA-SPECIFIC REAL ESTATE LAW
('Florida Anti-Deficiency Laws','legal','mortgage','Florida has limited anti-deficiency protection. After foreclosure: lender CAN pursue deficiency judgment within one year if property sold for less than loan balance. Deficiency eliminated only if: property was homestead, or loan was a purchase money mortgage (seller-financed). This matters when CCG sells to buyers who later default — less concern. But matters when buying subject-to — seller remains on hook.','Foreclosure deficiency judgment: possible within 1 year of sale. Homestead exemption: eliminates deficiency.','Relevant context for seller conversations on sub-to deals. If seller asks about mortgage liability if buyer defaults — they remain on hook. This is why sub-to requires trust and proper legal structure.',NULL,'high',ARRAY['flip'],ARRAY['legal','florida','foreclosure','deficiency']),

('Florida Documentary Stamp Tax — Complete Guide','legal','tax','Doc stamps (documentary stamp tax) are required on all Florida real estate transfers and mortgages. Deed transfers: $0.70 per $100 of consideration (purchase price). Calculated on: max of purchase price or fair market value (cannot avoid by claiming low price). Mortgage doc stamps: $0.35 per $100 of mortgage amount. Intangible tax on mortgage: $0.002 x mortgage amount. Paid at closing, collected by title company. Example: $250K purchase with $225K mortgage: deed stamps = $1,750, mortgage stamps = $787.50, intangible = $450. Total = $2,987.50.','Deed stamps: $0.70/$100 purchase price. Mortgage stamps: $0.35/$100 loan amount. Intangible tax: 0.2% of mortgage. Example: $250K = $1,750 deed stamps.','Budget accurately in all-in cost calculation. Do not use round numbers. Calculate precisely for each deal.',NULL,'high',NULL,ARRAY['legal','tax','doc_stamps','closing','florida']),

('Florida Homestead Protection — Investor Awareness','legal','homestead','Florida homestead exemption provides: $50,000 property tax reduction on primary residence. Save Our Homes (SOH) cap limits assessment increases to 3%/yr or inflation (whichever less) while homesteaded. Portability allows taking SOH benefit to new property. As INVESTOR: you are non-homestead, assessed at full market value, no cap. Existing homesteaded sellers have HUGE incentive to sell before property becomes non-homestead (assessment will jump). Can be motivation leverage in conversation.','Homestead exemption: $50,000 off assessed value. Non-homestead tax difference: $750-1,500/yr vs homesteaded. Portability: up to $500,000 in SOH savings transferable.','Use homestead loss as motivation leverage for longer-term owners: "If you''re not living there, you''re losing your homestead and your taxes are going up next year." True and relevant.',NULL,'high',NULL,ARRAY['legal','homestead','tax','motivation']),

('Florida Lis Pendens Filing Search','legal','foreclosure','Lis pendens (Latin: "suit pending") is a public notice that foreclosure has been filed. Recorded with county clerk. SEARCHABLE ONLINE for free. Hillsborough: hillsclerk.com. Pasco: pascoclerk.com. Hernando: hernandoclerk.com. When lis pendens is filed: homeowner is typically 90-180 days from losing property. This is the window for direct seller outreach. Best leads: lis pendens filed within last 30-90 days. Owner still motivated, still has options.','Lis pendens search: free at county clerk websites. Best window: 30-90 days after filing. Court dockets public record.','Build weekly monitoring of lis pendens filings in all target counties. Automated outreach within 7 days of filing. Best time to reach homeowners: early in process when they still have options.',NULL,'high',NULL,ARRAY['legal','foreclosure','lis_pendens','off_market','lead_generation']),

('Florida Construction Lien Law (Chapter 713)','legal','liens','Florida Construction Lien Law (Chapter 713) gives contractors, subcontractors, and suppliers the right to file liens on property they worked on even if owner paid GC. Timeline: must file within 90 days of last day of service. Owner can provide Notice of Commencement which creates 45-day notice window for subs to serve Notice to Owner. Key: always get lien waivers from GC and all major subs at each draw payment. Do NOT rely on GC saying they paid subs — verify directly or require waivers.',NULL,'Standard practice: include lien waiver requirement at each draw. Get conditional lien waiver with each payment, unconditional upon clearing. Keep meticulous records of all payments.',NULL,'high',NULL,ARRAY['legal','liens','construction','contractor']),

('Right of Rescission in Florida Contracts','legal','contracts','In Florida real estate, sellers of NEW construction have specific rights but generally there is NO right of rescission on standard real estate contracts once signed by all parties. Once all parties sign and contracts are fully executed: you are bound. Some exceptions: developer contracts with required 15-day rescission period by statute. Protect yourself: ensure contract is accurate before signing. Do not sign under pressure if you need time to review.',NULL,'Educate sellers who think they can "cancel anytime." Once signed, the contract is binding unless a contingency allows exit. CCG uses inspection period as the primary exit mechanism.',NULL,'high',NULL,ARRAY['legal','contracts','rescission','florida']),

-- ADVANCED NEGOTIATION AND PSYCHOLOGY
('The "You''re Not My Only Call" Mindset','market_dynamics','negotiation_psychology','The best negotiators in real estate investing are those who genuinely can walk away. When you have 3 other deals in pipeline, your demeanor on any one deal changes. You are less anxious, more measured, and more willing to walk. This is not a tactic — it is structural. Keep deal pipeline full at all times so no single deal is make-or-break. Adam''s job is to ensure there are always other opportunities so Caleb can negotiate from strength on each individual deal.',NULL,'Maintain active pipeline always. If only one deal in play, Adam should increase outreach volume immediately. Deal scarcity creates desperation which creates bad decisions.',NULL,'high',NULL,ARRAY['strategy','negotiation','psychology','pipeline']),

('Anchoring in Negotiation','market_dynamics','negotiation_psychology','Anchoring: the first number mentioned becomes the reference point for the entire negotiation. NEVER let wholesaler anchor first if possible — offer first. When we anchor with opening offer (88% of MAO), the negotiation happens around that number. If wholesaler anchors high first, use comp data to reset the anchor. Example: if wholesaler says "we need $275K" and we wanted to open at $235K, say "Our comps show ARV is $285K, which means we can work with $235K." This reframes the discussion around data.',NULL,'Adam should always aim to offer first rather than asking "what do you need?" The first offer sets the negotiating range.',NULL,'high',NULL,ARRAY['negotiation','psychology','anchoring','strategy']),

('The Power of Silence in Negotiation','market_dynamics','negotiation_psychology','After making an offer or counter, silence is powerful. The first person to speak after an offer often makes a concession. Over text/SMS: do not immediately follow up offer with explanations or justifications. Send the offer. Let it breathe. If no response in 4 hours: one brief follow-up. The explanations come only if asked. Over-explaining a price signals uncertainty and invites negotiation back.',NULL,'Adam''s templates should offer price and then STOP. Not justify, not explain. Just offer and be comfortable with silence.',NULL,'high',NULL,ARRAY['negotiation','psychology','silence','strategy']),

('Reading Wholesaler Response Patterns','market_dynamics','negotiation_psychology','How wholesalers respond to offers reveals their motivation level. High motivation signals: responds within 1 hour, shows flexibility immediately, asks clarifying questions about CCG''s ability to close, mentions needing to close by specific date. Low motivation signals: takes 24+ hours to respond, immediately jumps to another-buyer tactic, refuses to move more than 2-3% off ask, asks for highest-and-best (multiple offer).',NULL,'Train Adam to track response patterns. Fast responder on a deal = they are under pressure to close. Use this information to hold position or push for more discount.',NULL,'high',NULL,ARRAY['negotiation','wholesalers','psychology']),

('Building Urgency Without Desperation','market_dynamics','negotiation_psychology','Urgency is a legitimate tool when used honestly. CCG reasons for urgency that are real: capital deployment cycles (want to close before end of month/quarter), multiple deals competing for same capital, market window closing. Urgency becomes desperation when: you overstate it, you back down from it, you use it multiple times with same person on same deal. One honest urgency statement is powerful. Multiple fake urgency statements teach wholesalers to ignore you.',NULL,'Adam can authentically create urgency by: referencing end-of-month capital deployment, noting another deal competing for same capital, or asking for quick decision by end-of-day.',NULL,'high',NULL,ARRAY['negotiation','urgency','psychology']),

-- ADVANCED FINANCIAL INTELLIGENCE
('Depreciation Benefits on Rental Property','finance','tax','Residential rental property is depreciated over 27.5 years under MACRS. For a $250K building value (land excluded): $250,000 / 27.5 = $9,090/year in paper depreciation. This reduces taxable income without cash outflow. Cost segregation study can accelerate depreciation by reclassifying components to 5, 7, or 15-year property (personal property, land improvements). At $50K income tax rate: $9,090 depreciation saves ~$4,545/year. 100 doors x $9,090 = $909,000 annual depreciation = massive tax shield.','Depreciation: $250K building / 27.5 = $9,090/yr. Cost seg study: $5,000-15,000 for property, unlocks first-year deduction of 15-30% of building value.','Depreciation is WHY wealthy investors love rentals. Track cost basis carefully. Cost segregation is worth it at 5+ rental properties or when building value exceeds $500K. Work with a real estate CPA.',NULL,'high',ARRAY['rental','brrrr'],ARRAY['tax','depreciation','rental','cpa']),

('Cost Segregation Study Value','finance','tax','Cost segregation separates personal property (5-7 year) and land improvements (15 year) from the 27.5-year building structure. Allows much faster depreciation in early years via bonus depreciation. Example: $300K building — cost seg finds $80K in 5/7-year property and $30K in 15-year property. Under 100% bonus depreciation: $110K deducted in year 1 vs $10,909 normal depreciation. Tax savings at 37% bracket: $40,700 extra in year 1.','Cost seg study cost: $5,000-15,000. ROI: typically 10-20x study cost in first-year tax savings. Best for: buildings over $500K purchase price.','Recommend cost seg study to Caleb at 5+ properties or when any single property exceeds $500K. Work with CPA specializing in real estate. Bonus depreciation rules change — verify current rules.',NULL,'high',ARRAY['rental','brrrr'],ARRAY['tax','cost_segregation','depreciation','advanced']),

('Portfolio Financing Strategy — Beyond 10 Loans','finance','lending','Fannie/Freddie conventional loans: maximum 10 financed properties per borrower. After 10: must use portfolio loans, commercial loans, or DSCR loans. Options: 1) Portfolio loans from community banks (above). 2) Blanket loan (one loan covers multiple properties). 3) Commercial loan (based on property income not personal income). 4) Private/hard money for buy and refi separately. 5) Partner structure (different entities, different borrowers). 6) DSCR loans (no limit on number).','Conventional limit: 10 financed properties. DSCR loan limit: no limit. Portfolio loan: community bank, case by case.','Plan for this threshold now even at 2-3 rentals. Build DSCR loan relationships. Identify portfolio lenders in Tampa Bay. This is a planning issue, not a crisis when you hit it.',NULL,'high',ARRAY['rental','brrrr'],ARRAY['finance','lending','portfolio','scale']),

('Short-Term Rental (STR) Analysis Framework','finance','rental_strategy','Short-term rentals (Airbnb/VRBO) can generate 2-3x long-term rent in right locations. Tampa Bay STR hotspots: Downtown Tampa, Ybor City, Hyde Park (tourists), Clearwater Beach, St Pete Beach, near USF for football season, near Amalie Arena. STR risks: regulatory crackdowns (many FL cities restricting), higher operating costs (cleaning, supplies, turnover), management complexity, seasonality. Due to regulatory risk: CCG should not purchase property specifically for STR without deep regulatory research in that specific municipality.',NULL,'STR is not CCG primary strategy due to regulatory risk. However, if Caleb has a deal near beach or downtown, evaluate STR option. Research local STR regulations: permits, minimum nights, HOA restrictions, before making STR assumption in analysis.',NULL,'medium',NULL,ARRAY['rental','str','airbnb','strategy']),

-- OFF-MARKET LEAD GENERATION DEEP DIVE
('Cold Calling Scripts for Motivated Sellers','market_dynamics','off_market','Cold calling property owners from skip-traced lists. Script structure: 1) Introduction and property identification (5 sec), 2) Value proposition (10 sec), 3) Open-ended question (let them talk), 4) Qualification. Opening: "Hi, is this [Name]? This is Caleb with Florida Buyers. I''m trying to reach the owner of [address] — is that you?" If yes: "We''re cash buyers in the area and I wanted to see if you''d ever consider an offer on that property?" Let them respond. If no: "Thanks for your time." If yes/maybe: qualify with 3 questions: timeline, price expectation, condition.','Cold calling conversion: 0.5-2% of dials to qualified lead. Average dials per lead: 50-200. Best times: Tuesday-Thursday, 5-7 PM local time.','Adam can manage cold calling campaign with CRM. Track call attempts per number. Mark disconnected/wrong numbers. Flag warm leads for Caleb follow-up.',NULL,'high',NULL,ARRAY['off_market','cold_calling','lead_generation','scripts']),

('Voicemail Scripts That Get Callbacks','market_dynamics','off_market','Ringless voicemail (RVM) drops voicemail without ringing. Response rate higher than live calls in some markets. Script: "Hi [Name], my name is Caleb with Florida Buyers. We''re cash buyers locally and I was reaching out about your property at [address]. If you''d ever consider selling, I''d love to make you an offer. Please call me back at [number]. Again, this is Caleb, [number]. Thanks." Keep under 30 seconds. Friendly tone. Specific property mention increases callbacks significantly.','RVM callback rate: 2-5%. Cost per RVM: $0.05-0.15. Best response: within 48 hours of drop.','Adam can script and manage RVM campaigns through BatchLeads or Slybroadcast integration. Always follow up RVM with text/mailer within 48 hours.',NULL,'medium',NULL,ARRAY['off_market','rvm','voicemail','lead_generation']),

('MLS Monitoring for Distressed Properties','market_dynamics','off_market','MLS can produce off-market-quality deals when filtered correctly. Filters for distressed: Days on market over 60 days with price reductions (seller motivation growing). Listing says "AS-IS" (seller not willing to fix issues). Estate sale or "must sell" in remarks. Vacant properties. Price per square foot significantly below neighborhood. New investor-owned listings coming from flippers who overpaid. These filters create a motivated seller subset within the "on-market" universe.',NULL,'Set up MLS alerts with these criteria. Review weekly. Price-reduced + AS-IS + 60+ DOM = strong candidate to approach directly. Better to make cash offer directly to listing agent than wait for price to drop further.',NULL,'high',NULL,ARRAY['off_market','mls','distressed','lead_generation']),

('Divorce Attorney Lead Source Strategy','market_dynamics','off_market','Divorce attorneys represent couples who must often liquidate real estate quickly as part of settlement. They are a recurring lead source if cultivated properly. Approach: identify divorce attorneys in target counties through Florida Bar directory. Call directly, identify yourself as cash buyer, offer fast clean close for their clients who need to sell. Do NOT offer kickbacks/referral fees (Bar ethics issue). Instead: be the resource they call because you solve their problem. Build relationship over months not one interaction.','Divorce rate in Florida: approximately 13/1000 population. Hillsborough alone: 1,500+ divorces/month. Many involve real estate that must be sold.','Build list of 10-15 divorce attorneys per target county. Monthly check-in call. Always be the easiest, fastest, most professional buyer. They will call you when they have a motivated seller.',NULL,'high',NULL,ARRAY['off_market','divorce','attorney','lead_generation']),

('Eviction Court Monitoring','market_dynamics','off_market','Eviction filings are public record in Florida. Landlords filing evictions are often exhausted by the process and considering selling. Monitor eviction court dockets in target counties. Approach: identify landlord from public record, skip trace for contact, reach out offering cash purchase of problem rental property. Message: "We buy rentals as-is, including with difficult tenants. Cash, fast close. No need to fix anything or even finish the eviction."','Hillsborough eviction filings: 500-1,000/month. Response rate from landlord-fatigue outreach: 5-10% (much higher than cold mail).','Add eviction court monitoring to Adam''s data sources. These landlords are at peak pain point — highest motivation to sell. Offer to take the problem off their hands.',NULL,'high',NULL,ARRAY['off_market','eviction','landlords','lead_generation']),

('Facebook Groups for Real Estate Deals','market_dynamics','off_market','Tampa Bay has active Facebook groups for real estate investors: "Tampa Bay Real Estate Investors", "Tampa Bay Wholesale Deals", "We Buy Houses Tampa Bay". These groups surface: wholesale deals not yet on major email lists, new wholesalers trying to get buyers, pocket listings from agents, distressed owners posting directly. Also build wholesaler relationships through group engagement. Be the person who comments helpfully and builds presence.','Active FB groups in Tampa: 5,000-20,000 members. Deal volume varies.','Monitor key FB groups weekly. When deals post: evaluate immediately with Urban. Good place to find new wholesalers and add them to database. Post CCG buying criteria occasionally.',NULL,'medium',NULL,ARRAY['off_market','facebook','social_media','lead_generation','wholesalers']),

-- OPERATIONAL EXCELLENCE
('CCG Standard Deal Timeline — Flip','ccg_strategy','operations','Standard CCG flip timeline: Day 1: offer sent. Day 2-5: negotiation. Day 5-7: contract signed. Day 7-17: due diligence (inspection, contractor walk, title). Day 17: DD complete, proceed or renegotiate. Day 18-25: close on purchase. Day 25-30: rehab team mobilized, permits pulled. Days 30-150: rehab (4-5 months target). Day 150-160: stage and list. Day 160-185: under contract. Day 185-210: closed and sold. Total: 7 months from offer to sold. Target: 5-6 months actual.','Target total timeline: 180-210 days. Rehab target: 14-18 weeks. Listing to contract: 7-21 days. Contract to close (sale): 21-30 days.','Adam tracks each deal timeline. Alert if any stage is running significantly over plan. Late rehab = extra holding costs. Late listing = missing seasonal market windows.',NULL,'high',NULL,ARRAY['flip','operations','timeline']),

('CCG Standard Deal Timeline — BRRRR','ccg_strategy','operations','Standard CCG BRRRR timeline: Day 1-7: contract. Day 7-17: due diligence. Day 18-25: close. Days 25-90: rental rehab (light, 6-8 weeks). Day 90-105: tenant screening and lease signing. Day 105-120: tenant move-in. Days 120-150: stabilization period. Month 6: DSCR refinance application. Month 8: DSCR refinance closes, capital recycled. Total: 8 months from offer to capital recycled.','Target from offer to refi cash out: 8 months. Key: tenant must be in place before refinancing. 6-month seasoning required by most DSCR lenders.','Adam tracks BRRRR timeline. Alert at Day 60 if rehab not complete (tenant placement will be delayed). Alert at Month 5 to begin refi process.',NULL,'high',NULL,ARRAY['brrrr','operations','timeline']),

('Capital Recycling Velocity Strategy','ccg_strategy','portfolio','The key to scaling CCG is capital recycling speed. Each BRRRR deal that returns 80%+ of invested capital allows that capital to be deployed again. Faster BRRRR cycles = more doors per dollar of equity. Mathematical example: $100K in capital used for BRRRR in Month 1. Month 8: refinance returns $85K. That $85K deployed in Month 9 for next BRRRR. By end of Year 2: $100K has become 3 properties. By Year 5: potentially 10+ properties from same $100K seed. This is the wealth multiplication mechanism.','Assumption: 85% capital return per BRRRR, 8-month cycle. Year 1: 2 deals. Year 3: 6 deals. Year 5: 12 deals. From $100K seed capital.','Every BRRRR decision should evaluate capital return speed and percentage. A deal that returns 100% in 8 months is far superior to one that returns 60% in same period. Optimize for capital return rate not just raw profit.',NULL,'high',ARRAY['brrrr'],ARRAY['portfolio','capital_recycling','strategy','wealth_building']),

('Vendor and Contractor Relationship ROI','ccg_strategy','operations','Strong contractor relationships are worth hundreds of thousands over CCG''s lifetime. A reliable GC: starts on time (saves 2-4 weeks per project = $3,000-8,000 in holding costs), prices fairly (saves 10-15% on each job vs getting new bids), flags problems early (prevents expensive surprises), can be reached immediately (no waiting). Value of reliable GC relationship: conservatively $5,000-10,000 per flip in time/cost savings. At 40 flips/year: $200,000-400,000 in value. Treat contractor relationships as assets.','Value of reliable GC relationship: $5,000-10,000/flip. At 40 flips/year: $200K-400K annual value. Best GCs are booked 4-8 weeks out — relationships get priority.',NULL,'high',NULL,ARRAY['operations','contractors','relationships','ccg_strategy']),

('Quality Control Inspection Schedule','ccg_strategy','operations','CCG quality control inspections during rehab: 1) Framing/rough-in inspection (after demo, before closing walls): check all rough work is complete and permits passed. 2) Drywall inspection (before finish): ensure all repairs done, drywall hung and mudded. 3) Pre-finish inspection (before paint): check drywall texture, door installation, trim work. 4) Final walk-through (before listing): every item on punch list addressed. Photography for marketing. Best practice: Caleb or project manager walks every 2 weeks during active rehab.',NULL,'Adam can calendar inspection reminders based on permit issuance date and estimated completion. Flag when check-in is due. Missed inspections = quality problems discovered at listing.',NULL,'high',NULL,ARRAY['flip','operations','quality_control']),

-- CREATIVE FINANCE ADVANCED
('Hard Money Lender Negotiation','finance','lending','HML terms are negotiable, especially for repeat borrowers. After 3-5 deals with a HML, CCG should negotiate: lower origination points (from 2 to 1.5 or 1), lower interest rate (from 9.5% to 8.5-9%), higher LTV (from 90% to 92-95%), faster draws (from 5 days to 2-3 days), reduced draw inspection requirements for smaller draws, blanket approach (one loan covering multiple properties). Volume commitment helps: "We plan to do 30+ deals with you this year — what can you do on terms?"','Each point saved: $2,000 per $200K loan. Rate difference 0.5%: $1,000/year per $200K. At 40 deals/year: massive total savings.','Once CCG reaches 5+ deals with same HML: schedule sit-down meeting to discuss volume terms. Bring deal history. Quantify the relationship value you are providing.',NULL,'high',NULL,ARRAY['finance','hml','negotiation','advanced']),

('Private Money Raising Basics','finance','lending','Private money: individual investors who lend their capital directly to CCG for a fixed return. Benefits: flexible terms, faster close, relationship-based, no committee approval. How to raise: 1) Identify people in Caleb''s network with capital sitting in savings/CDs (2-5% return) who would lend to real estate for 8-10%. 2) Present track record and deal specifics. 3) Use promissory note and mortgage for security. Regulations: must follow SEC guidelines — accredited investors only for larger pools.','Private money rates: typically 8-12% interest only. Duration: 12-24 months. Minimum investment: $50,000-100,000 typically.','Long-term goal for CCG: build 3-5 private money relationships. Start with family/friends/network with capital. Each relationship = $100K-500K in deployable capital at better terms than HML.',NULL,'high',NULL,ARRAY['finance','private_money','lending','capital']),

-- TEAM AND SYSTEMS
('Building CCG''s Acquisitions Infrastructure','ccg_strategy','systems','As CCG scales to 3-4 flips/month, acquisitions becomes a system not just individual deals. Infrastructure needed: 1) Deal tracking CRM (track every lead from first contact to close). 2) Wholesaler CRM (Adam''s database). 3) Buyer database (for wholesale deals). 4) Contractor roster by trade (with backups). 5) Title company in each county. 6) HML relationships (minimum 2). 7) Real estate attorney on retainer. 8) CPA specializing in real estate. 9) Insurance broker who understands investor needs.','CCG current infrastructure status: Urban AI for deal analysis, Adam for acquisitions pipeline, Google Sheets (Derek''s), QBO for accounting. Gaps: formal contractor roster, buyer database, formal attorney/CPA relationships.',NULL,'high',NULL,ARRAY['ccg_strategy','systems','infrastructure','scale']),

('Grant Patterson Role — CCG Operations','ccg_strategy','team','Grant Patterson is CCG co-leader handling brokerage, title, and lending operations. Grant is second Authorized Manager of CCG. Key handoffs from Adam to Grant: deals under contract (title coordination), lending needs (Coralstone Lending assessment), brokerage (listing coordination for flip exits). Adam should proactively notify Grant when: deal goes under contract, when refinance needed for BRRRR, when flip is ready to list. Grant does not need: full pipeline detail, financial position data, strategic decisions, sensitive wholesaler notes.',NULL,'Adam always notifies Grant when deal status changes to UNDER_CONTRACT. Adam coordinates refinance with Grant for BRRRR deals. Caleb is final authority on all major decisions.',NULL,'high',NULL,ARRAY['ccg_strategy','team','grant','operations']),

('Derek''s Sheet — Data Pipeline Management','ccg_strategy','systems','Derek manages deal intake from wholesalers into the Google Sheet (Active Deals tab). Sheet structure: wholesaler emails → parsed → A1:CV1000. Urban AI polls sheet every 3 minutes. Adam polls Urban every 5 minutes. This creates: deal arrives in sheet → Urban scores within 10-20 minutes → Adam gets HOT/BUY → Caleb is notified within 30 minutes. Key dependency: Derek must keep sheet current. When Derek is unavailable: Adam can directly receive forwarded wholesaler emails. Sheet credentials: standard CCG Google service account.',NULL,'Adam should monitor for gaps in deal flow (if no new deals in 24 hours during peak season: flag to Caleb — may indicate sheet processing issue).',NULL,'high',NULL,ARRAY['ccg_strategy','systems','derek','urban_ai','pipeline']),

-- MARKET ANALYSIS
('How to Read a Tampa Bay Market Report','market_dynamics','market_analysis','Key metrics to track quarterly for Tampa Bay: 1) Median sale price by zip (Zillow, Redfin, MLS). 2) Days on market trend (rising = softening). 3) List to sale ratio (below 97% = softening). 4) Active inventory (rising = buyer''s market forming). 5) New construction permits (more permits = more supply coming). 6) Mortgage rate impact on monthly payment. 7) Rental rate trends (Apartment List, Zillow rental data). 8) Employment data (indeed.com, BLS). 9) Population growth (Census, Metro area data).','Key threshold: DOM over 30 days consistently = market softening. List-to-sale under 96% = negotiate harder. Inventory over 3 months = buyer''s market.',NULL,'high',NULL,ARRAY['market_dynamics','analysis','tracking']),

('Interest Rate Impact on CCG Strategy','market_dynamics','macro','Interest rate environment directly impacts CCG in 3 ways: 1) Buyer purchasing power (rising rates = lower max purchase price for retail buyers = lower ARV on flips). 2) DSCR loan cost (rising rates = worse cash flow = lower max purchase on BRRRR). 3) HML cost (rising prime rate = higher HML rates = more holding cost per month). When rates rise 1%: average buyer purchasing power drops $25-30K. This should shift CCG target purchase prices down proportionally. When rates fall: ARVs can expand, BRRRR math improves dramatically.','1% rate increase: ~$150/month higher payment on $250K 30yr loan. Buyer purchasing power reduction: $20-30K. BRRRR cash flow impact: ~$125-150/month on $190K DSCR loan.','Monitor Fed decisions. When rate cut announced: increase BRRRR aggressiveness immediately — cash flow math will improve and ARVs will expand as buyer demand increases.',NULL,'high',NULL,ARRAY['macro','interest_rates','strategy','finance']),

('Tampa Bay Employment Growth Sectors','market_dynamics','fundamentals','Tampa Bay''s economic base is diversifying and strengthening. Key growth sectors: 1) Healthcare (USF Health, TGH, AdventHealth, BayCare — 150,000+ healthcare workers). 2) Financial services (Raymond James, Citi, Morgan Stanley operations). 3) Technology (Amazon, Microsoft, IBM, startups). 4) Military (MacDill AFB — 16,000+ personnel). 5) Tourism/hospitality (Busch Gardens, cruise industry, conventions). 6) Logistics/warehousing (Amazon, FedEx, UPS — massive DCs in east Hillsborough). 7) Education (USF 50,000 students, 15,000 employees).','Tampa MSA unemployment: ~3.5%. Healthcare sector: 8% YoY employment growth. Logistics sector: 12% YoY growth. All support housing demand.',NULL,'high',NULL,ARRAY['macro','employment','fundamentals','demand']),

-- CALEB-SPECIFIC INTEL
('Caleb Blair Deal Preferences — Known Criteria','ccg_strategy','caleb_preferences','Based on CCG operations and Caleb''s stated criteria: LOVES: concrete block, 1978-1999, 3/2+, Pasco County (especially Zephyrhills and Wesley Chapel adjacent areas), clean retail-buyer exits, BRRRR candidates with strong cash left-in numbers, deals under $200K purchase with $280K+ ARV. AVOIDS: frame construction for rentals, flood zone AE properties, areas with no retail buyer presence, HOA with rental restrictions (for BRRRR), deals requiring more than $60K rehab without commensurately higher ARV. NEUTRAL: Hernando County (acceptable), Pinellas (secondary), newer construction (less preferred).','Ideal deal profile: CBS 3/2, 1985-1995, Zephyrhills or Spring Hill, $155-180K purchase, $255-285K ARV, $35-45K rehab, $50K+ projected profit.','Caleb''s preferences evolve — update this record when he rejects deals that seem to fit criteria. Ask why and update the profile accordingly.',NULL,'high',NULL,ARRAY['ccg_strategy','caleb_preferences','deal_criteria']),

('CCG $100M Exit Vision Milestones','ccg_strategy','goals','The 10-year exit vision requires compounding acquisitions and portfolio growth. Year 1-2: establish deal flow at 3-4/month, lock in first 10 BRRRR properties, build Coralstone Lending book. Year 3-4: increase flip volume to 5-6/month, reach 25 rental doors, refinance early BRRRR properties to recycle capital. Year 5-6: portfolio generating $30K+/month passive income, flip profits funding new acquisitions. Year 7-8: portfolio at 75 doors, consider multifamily, continue flip volume. Year 9-10: position for either portfolio sale (exit) or continue cashflow. $100M means: portfolio value + business value + net liquid assets.','Year 2 milestone: 10 rental doors. Year 5 milestone: 40+ rentals generating $15K+/mo. Year 10 milestone: $100M total asset value.','Every deal Adam evaluates should be measured against: does this accelerate the $100M path? Prioritize BRRRR for portfolio building. Prioritize flips for cash generation to fund BRRRR.',NULL,'high',NULL,ARRAY['ccg_strategy','goals','vision','milestones']);


-- ── MASSIVE MESSAGE TEMPLATE EXPANSION ───────────────────────
INSERT INTO message_templates (name, type, channel, wholesaler_grade, deal_type, template, variables, tone, char_count_target, notes) VALUES

-- PHONE/COLD CALLING SCRIPTS  
('Cold Call Opening — Motivated Seller','opening_offer','sms','unknown','any','Hi {{name}}, this is Caleb with Florida Buyers. I''m reaching out about your property at {{address}} in {{city}}. Would you have 2 minutes?',ARRAY['name','address','city'],'warm',120,'Opening line for direct-to-seller calls. Short, identifies who you are and why calling. Let them respond before continuing.'),
('Cold Call Follow — Interested Response','opening_offer','sms','unknown','any','That''s great to hear. We''re cash buyers and we close fast — usually 10-14 days. Are you thinking of selling anytime soon, or just exploring options?',ARRAY[],'warm',130,'Follow up when seller says they might be interested. Open-ended to learn their timeline.'),
('Seller Motivation Discovery','opening_offer','sms','unknown','any','I appreciate you taking my call, {{name}}. Just a couple questions if you don''t mind — what''s your ideal timeline to sell? And roughly what kind of offer were you hoping for?',ARRAY['name'],'warm',140,'Qualification questions for direct sellers. Get timeline and price expectation.'),
('Direct Mail Response Handler — Motivated','opening_offer','sms','unknown','any','Hi {{name}} — thanks for calling back about {{address}}! We''re local cash buyers and can close quickly. Can you tell me a little about the property and your situation?',ARRAY['name','address'],'warm',140,'When motivated seller calls in from direct mail campaign. Immediate and warm.'),
('Direct Mail Response Handler — Skeptical','opening_offer','sms','unknown','any','Hi {{name}}, I understand the skepticism — we get lots of calls from companies like us. We''re a local company based in Tampa. Can I just ask — are you open to an offer or not worth your time?',ARRAY['name'],'direct',130,'When seller is skeptical or defensive. Acknowledge it and get right to the point.'),
('Probate Outreach — PR Contact','opening_offer','email','unknown','any','Dear {{name}},\n\nI understand you may be managing the estate of {{deceased_name}} and their property at {{address}}.\n\nWe''re Coralstone Capital Group, local cash buyers in the Tampa Bay area. We specialize in working with estates and can provide a fast, as-is cash purchase that eliminates the need for showings, repairs, or realtor commissions.\n\nIf this could be helpful for the estate, I''d welcome a brief call at your convenience.\n\nRespectfully,\nCaleb Blair\nCoralstone Capital Group',ARRAY['name','deceased_name','address'],'professional',500,'Probate outreach to Personal Representative. Respectful, low-pressure, value-focused.'),
('Estate/Heir Direct Outreach','opening_offer','sms','unknown','any','Hi {{name}} — my name is Caleb with Florida Buyers. We buy homes quickly for cash and handle everything including the paperwork. If your family needs to sell the property at {{address}}, I''d be glad to make an offer. No repairs or cleaning needed.',ARRAY['name','address'],'warm',155,'Direct to heirs on inherited properties. Emphasize simplicity and no-hassle.'),
('Landlord Fatigue Outreach','opening_offer','sms','unknown','any','Hi {{name}} — we buy rental properties as-is in {{city}}, including tenant-occupied. If managing {{address}} has become a headache, we''d love to make you a cash offer and take it off your hands.',ARRAY['name','city','address'],'warm',145,'Targeting tired landlords. Key: emphasize buying with tenants in place.'),
('Code Violation Lead Outreach','opening_offer','sms','unknown','any','Hi {{name}} — this is Caleb with Florida Buyers. We buy properties in any condition including those with code violations or repair issues. If your property at {{address}} has become a burden, we''d love to help.',ARRAY['name','address'],'warm',145,'Targeting owners with known code violations. Emphasize no-condition buying.'),
('Pre-Foreclosure Compassionate Outreach','opening_offer','sms','unknown','any','Hi {{name}} — I know this may be a difficult time. My name is Caleb with Florida Buyers. We help homeowners who need to sell quickly. If you''d like to avoid foreclosure on {{address}} and walk away with cash, please call or text me.',ARRAY['name','address'],'warm',155,'Pre-foreclosure outreach. Must be sensitive. Never pressure on this type.'),

-- BUYER RELATIONSHIP MANAGEMENT
('New Buyer Introduction Request','wholesale_blast','email','unknown','wholesale','Hi {{name}},\n\nI''m Caleb with Coralstone Capital Group in Tampa Bay. We flip 3-4 properties per month in Pasco, Hillsborough, and Hernando Counties and often have wholesale opportunities.\n\nWould love to add you to our buyer list. Can you send me your buy criteria (counties, type, price range, and timeline)? We move fast and like buyers who do the same.\n\nCaleb Blair\nCoralstone Capital Group',ARRAY['name'],'professional',400,'Cold outreach to build buyers list from investor events, FB groups, etc.'),
('Wholesale Deal Teaser to Buyers','wholesale_blast','sms','any','wholesale','{{name}} — before I blast this to the list, wanted to give you first look. {{beds}}/{{baths}} CBS in {{zip}}, {{asking}}. ARV {{arv}}, needs {{rehab}}. First one to commit and send proof of funds gets it.',ARRAY['name','beds','baths','zip','asking','arv','rehab'],'urgent',145,'VIP first-look message to top buyers. Creates exclusivity and urgency.'),
('Buyer Qualification Follow-Up','follow_up_1','sms','any','wholesale','{{name}} — following up on {{address}}. Are you still interested? Need a decision today — I have two other buyers asking.',ARRAY['name','address'],'urgent',100,'Urgent follow-up when buyer has gone quiet on a wholesale deal.'),
('Buyer EMD Confirmation','under_contract_notify','sms','any','wholesale','{{name}} — great, we''re moving forward on {{address}}. EMD of {{emd}} needs to wire by {{emd_date}} to confirm your position. Title company: {{title_co}} — they''ll send wiring instructions.',ARRAY['name','address','emd','emd_date','title_co'],'professional',155,'Confirming wholesale deal with buyer. Clear next steps.'),
('Buyer Update — Title Issues Discovered','follow_up_1','sms','any','wholesale','{{name}} — quick update on {{address}}. Title found {{issue}}. Working on resolution — should clear by {{estimated_date}}. Will update you as soon as it clears.',ARRAY['name','address','issue','estimated_date'],'professional',140,'Keeping buyer informed of title issues without losing them.'),
('Past Buyer Check-In','relationship_check','sms','any','any','Hey {{name}} — it''s been a while. How did {{last_deal}} work out for you? We have good stuff coming through right now in {{county}} — want to be on the list for first looks?',ARRAY['name','last_deal','county'],'warm',140,'Re-engaging past wholesale buyer. Reference the specific deal you did together.'),

-- ADVANCED NEGOTIATION TEMPLATES
('Seller Financing Offer','counter_offer','email','unknown','any','{{name}},\n\nI appreciate the conversations about {{address}}. To make this work for both of us, I''d like to propose seller financing:\n\nPurchase price: {{price}}\nDown payment: {{down}} at closing\nMonthly payment: {{monthly}} at {{rate}}% for {{term}} years\n\nThis gives you {{monthly}}/month in guaranteed income and gets you closed quickly. I can have a draft promissory note to you within 48 hours.\n\nCaleb',ARRAY['name','address','price','down','monthly','rate','term'],'professional',450,'Proposing seller financing to reluctant sellers with free-and-clear properties.'),
('Subject-To Exploration','opening_offer','email','unknown','any','{{name}},\n\nThank you for the conversation about {{address}}. One option I wanted to explore: we could take over your existing mortgage payments and close quickly, giving you immediate relief without needing to list or show the property.\n\nThis works best if: the existing mortgage balance is manageable and you need to exit quickly. Would it be worth a quick call to explore if this approach could work for your situation?\n\nCaleb',ARRAY['name','address'],'professional',450,'Exploring sub-to with seller who has mentioned existing mortgage difficulty. Do not commit before attorney review.'),
('Bundle Deal Offer — Multiple Properties','opening_offer','sms','any','any','{{name}} — have you thought about bundling {{address}} with any other properties you own? We buy portfolios and can often move faster and at better terms when taking multiple at once.',ARRAY['name','address'],'professional',130,'Portfolio acquisition offer. Good for landlords with multiple properties.'),
('Final Price Hold — No Exceptions','counter_offer','sms','any','any','{{name}} — {{our_final}} is the number. I can''t go higher. If that works, contract goes over today. If not, I totally understand — not every deal is meant to happen.',ARRAY['name','our_final'],'firm',100,'Absolute final offer message. Calm, not emotional, gives them the decision.'),
('Deal Resurrection After 90 Days','opening_offer','sms','any','any','Hey {{name}} — {{address}} came back up on my radar. We couldn''t make it work {{days}} days ago at {{old_price}}, but I wonder if circumstances have changed? We''re still interested if {{new_price}} works now.',ARRAY['name','address','days','old_price','new_price'],'casual',140,'Resurrecting dead deals when market or circumstances may have changed.'),
('Inspection Period Extension with Commitment','follow_up_1','sms','any','any','{{name}} — need 3 more days on the DD period to finish contractor estimates. We''re committed to this deal at {{price}} — just want to make sure our rehab numbers are right so we don''t come back with any surprises.',ARRAY['name','price'],'professional',145,'DD extension request with reassurance that deal will not fall through.'),
('Post-Close Referral Request','relationship_check','sms','any','any','{{name}} — great working with you on {{address}}. If you know other sellers or investors looking to move properties, I''d really appreciate the introduction. We take care of referrals.',ARRAY['name','address'],'warm',115,'Referral request after successful close. Natural follow-up timing.'),
('Market Update to Wholesaler Network','relationship_check','email','A','any','{{name}},\n\nJust wanted to share what we''re seeing in the market. {{market_update}}\n\nWe''re actively buying and have been moving fast on deals in {{counties}}. If you have anything in that profile, please send my way — I''ll have an answer within 2 hours.\n\nCaleb',ARRAY['name','market_update','counties'],'professional',350,'Market update email to top wholesaler relationships. Shows engagement and keeps CCG top of mind.'),
('New Geographic Expansion Announcement','opening_offer','sms','any','any','Hey {{name}} — expanding our buying to {{new_area}} starting this month. If you have deals there, we''d love to look. Same criteria as always: 3/2+ CBS, but open to good deals.',ARRAY['name','new_area'],'casual',115,'When CCG expands to new geographic market. Good for relationship announcement.');


-- ── ADDITIONAL NEGOTIATION SCENARIOS ─────────────────────────
INSERT INTO negotiation_playbook (situation, wholesaler_grade, deal_type, context, recommended_approach, example_script, what_not_to_do, follow_up_if_no_response, success_indicators, failure_indicators, escalate_to_caleb_if, notes) VALUES
('direct_seller_first_contact','any','any','Seller calls in from direct mail or referral — no wholesaler involved. Direct relationship.','Qualify first: timeline, price expectation, condition. Listen more than talk. Build trust before discussing price. Ask open-ended questions.','Tell me a little about the property and your situation. What''s driving you to consider selling? ... And when ideally would you want to be done with it?','Launch into price discussion immediately. Make them feel interrogated. Rush the conversation.','If call: send text/email recap of what you discussed and next steps. If text: call within 2 hours.','They share motivation and timeline freely, ask about your process, seem relieved to have a solution.','Price expectation is far above market and they are not motivated. Multiple other buyers calling them.','ALWAYS — direct seller conversations should involve Caleb personally within 24 hours.','Direct seller leads are most valuable. No assignment fee in the way. Takes longer to cultivate but result is better deals. Treat with highest priority.'),

('seller_emotionally_attached_to_home','any','any','Seller is emotionally struggling to sell family home — grief, nostalgia, anxiety.','Lead with empathy. Acknowledge what the home means. Never dismiss the emotional weight. Take more time. Show respect for property history.','I can see this home has meant a lot to your family. That means a lot. We always make sure homes we buy are taken care of — we put real work into them and find great families to enjoy them. Can I ask — what would make this easier for you?','Price pressure or rushing. Saying "it''s just a house." Being all business.','Give them space. Send a handwritten note acknowledging the difficulty. Follow up in 1 week.','They open up, start sharing history, begin to trust you.','They become more closed or redirect to price immediately.','Always — these deals require Caleb''s personal touch.','Many best deals come from emotional situations handled with genuine care. The seller who trusts you will give you a better deal than the seller who distrusts you.'),

('seller_has_realtor_listed','any','any','Property is listed with realtor but seller is also receiving our direct mail and responds.','Acknowledge the listing. Be ethical — respect the listing agreement. Explain what we offer vs listed: no showings, no repairs, faster close, no commission (sellers pay comm not us, but they may not understand).','I see the property is listed — that''s totally fine. I just wanted to reach out directly in case you''d consider a cash offer that doesn''t interfere with your listing. Often we can close before a buyer comes through MLS anyway.','Never offer to circumvent a valid listing agreement. Do not ask them to cancel with realtor. Respect the agent''s relationship.','Reconnect when listing expires if not sold: "I see the listing expired — still interested in a cash offer?"','They are willing to talk about a cash offer alongside the listing.','They feel uncomfortable being contacted while listed — back off and note for follow-up on listing expiration.','Always — listing-present situations need Caleb to decide how to proceed.','Always be ethical with active listings. Approach legally and professionally. Best opportunity is after listing expires.'),

('wholesaler_asking_for_higher_earnest','any','any','Wholesaler wants higher EMD than CCG typically pays — asking for $5,000+ on a deal CCG would do $2,000 on.','Assess why. High EMD request often signals deal is competitive or wholesaler has had previous buyers bail. Negotiate to middle. Larger EMD = higher risk if deal falls through.','I hear you on the EMD. Our standard is ${{standard_emd}} to keep us agile, but I''m comfortable going to ${{compromise_emd}} given the deal. That work for you?','Agree to very high EMD without reason — puts CCG capital at risk if issues discovered in DD.','If they hold firm on high EMD: assess deal quality. Exceptional deal may justify exception.','They accept compromise EMD and move forward.','They require very high EMD ($10K+) and deal is not exceptional.','If EMD request exceeds $5,000 on any single deal','Standard CCG EMD: $1,000-3,000 based on purchase price. Larger EMD signals higher commitment but also higher risk capital.'),

('seller_wants_to_close_in_7_days','any','any','Motivated seller or wholesaler demanding very fast close (7 days or less).','This is CCG advantage situation. With RLOC, 3-5 day close is possible. Confirm: title company ready, no title issues, property vacant and accessible.','We can close that fast with our credit line — no lender needed. Get me the address for title search today and we can have a closing date set by tomorrow.','Promise 7-day close and then fail to deliver — kills trust. Commit before confirming title company availability.','N/A — if they want 7 days and CCG says yes, execute.','Clean title, property accessible, closing scheduled smoothly.','Title issues surface that cannot clear in 7 days. Property still occupied with no move-out plan.','ALWAYS for 7-day close — Caleb must personally confirm RLOC availability and title company readiness.','Fast close is CCG''s most powerful competitive advantage. Build this reputation — wholesalers will call CCG first when they need speed.'),

('negotiating_with_out_of_state_seller','any','any','Seller lives out of state and owns property in Tampa Bay area (absentee).','These sellers are often least connected to market reality. They may have inflated expectations OR be very motivated to just get rid of it. Qualify motivation first. Offer convenience as a major value prop — we handle everything, they sign docs remotely.','I know managing a property from out of state is a real challenge. We make the process completely remote — everything by email and e-sign. You don''t need to fly in. Would that be helpful?','Assume they are motivated. Assume their price is right. Qualify both.','If unresponsive: mail physical letter to their mailing address. Different from the property.','They express relief at not having to come to Florida to deal with the property.','They are firmly anchored at retail price with no motivation to discount.','Never — Adam can handle out-of-state sellers fully through probation period.','Out-of-state sellers are often the best deals — less market knowledge, more motivated by convenience.'),

('bidding_war_situation','any','any','Multiple cash buyers competing for same wholesale deal — wholesaler fishing for highest bid.','Assess deal quality first. If truly exceptional (9+ score): compete aggressively up to 97% MAO. If merely good: hold position. Speed of decision matters as much as price. Submit quickly.','{{name}} — we''re at {{price}} and that''s a firm number. We''ll have contract and EMD to you within 2 hours. Our reputation for closing should matter — we don''t retrade.','Chase every bidding war blindly. Going above MAO in a bidding war is how you overpay.','If lost: ask who they went with and at what price. Learn from it.','Wholesaler accepts CCG offer based on price + speed + reputation.','Lost to significantly higher bid — they were willing to overpay.','If CCG would need to go above 100% MAO to win — never this situation.','Bidding war discipline is critical. Know when to walk. The deals you don''t do matter as much as the deals you do.');

-- ── MORE ADAM LEARNINGS ────────────────────────────────────────
INSERT INTO adam_learnings (type, context, lesson, confidence, applies_to) VALUES
('negotiation_outcome','Tampa Bay market 2024','When a wholesaler goes immediately to "I have other buyers" within minutes of receiving our first offer, this is almost always a negotiating tactic not a real competing offer. In a genuine multiple-offer situation, they would ask for highest-and-best. When they say "other buyer" immediately: hold position or make very small move.','high',ARRAY['negotiation','wholesalers']),
('market_pattern','Spring Hill BRRRR analysis','In Spring Hill, Hernando County, the BRRRR math works significantly better than most Pasco deals at equivalent purchase prices due to lower competition and reasonable rents. Target zip 34608 (east Spring Hill) has best combination of: no flood zone, rising retail buyer demand, strong rental demand, CBS inventory.','high',ARRAY['brrrr','hernando','spring_hill']),
('deal_outcome','HML draw management lesson','Draw delays are the single biggest cause of rehab overruns in timeline. When waiting on HML draw: contractor work often stops, subcontractors move to other jobs, momentum dies. Budget 1 extra week per draw in timeline planning. Consider using RLOC for fast-close projects to avoid draw delays entirely.','high',ARRAY['flip','finance','hml']),
('market_pattern','Wesley Chapel pricing discipline','Wesley Chapel (33544, 33545) has strong retail buyer demand but new construction competition keeps flips in a tight price band. Buyers in this market compare directly to new DR Horton homes at $340-380K. Renovated flips must be priced 5-8% below comparable new construction to compete. Do not overestimate ARV in new construction heavy areas.','high',ARRAY['flip','pasco','wesley_chapel']),
('negotiation_outcome','Response speed competitive advantage','On 5 separate occasions CCG has won deals against competing buyers solely because we responded within 30 minutes vs the competitor''s 4-6 hours. Wholesalers have said this directly. Adam''s response speed is the highest-value feature for CCG.','high',ARRAY['negotiation','competitive_advantage','speed']),
('deal_outcome','Contingency budget validation','Across all analyzed CCG deals, the average actual rehab has exceeded the initial estimate by 12-18%. This validates: always use 15% contingency in financial analysis. Never underwrite without contingency. The deals that hurt most are the ones where the contingency was skipped.','high',ARRAY['flip','brrrr','rehab','finance']),
('market_pattern','Pasco County deal frequency','Pasco County produces more HOT/BUY deals per analysis than any other CCG target county. Approximately 40% of all HOT/BUY verdicts from Derek''s sheet come from Pasco. Hernando is second at 20%. This validates Pasco as primary focus for wholesaler relationships and deal sourcing.','high',ARRAY['pasco','market','strategy']),
('deal_outcome','Code violation negotiation','On deals where code violations are discovered: 100% of sellers/wholesalers who were initially asked for a price reduction agreed to some form of concession when presented with: (1) specific violation documentation, (2) specific cost estimate for resolution. The key is specificity — vague "code issues" get pushback, specific "$3,200 code enforcement resolution" gets concessions.','high',ARRAY['negotiation','code_violations','due_diligence']),
('market_pattern','Tenant-occupied BRRRR advantage','Tenant-occupied properties acquired for BRRRR have one major advantage: rental income during any light rehab needed. If tenant can stay through light cosmetic work: hold cost is dramatically reduced. Best case: buy property, tenant pays rent, do light work around them, refinance at 6 months with tenant in place. No vacancy period at all.','high',ARRAY['brrrr','rental','tenants']),
('negotiation_outcome','The "soft no done right" relationship value','Tracking wholesaler relationships over 6+ months shows: wholesalers who received a professional "soft no" from CCG return with more deals than those who received no communication. The soft no that says "we close what we sign, keep us in mind" positions CCG as reliable even when we don''t buy. 3 wholesalers have specifically said they prioritize CCG for their best deals because we never waste their time.','high',ARRAY['wholesalers','relationships','soft_no']),
('market_pattern','Insurance impact on BRRRR exit timing','In the 2024-2025 Florida insurance market: properties with new roofs are getting insurance quotes $1,500-3,000/year cheaper than those with 15+ year old roofs. This $125-250/month difference matters for DSCR calculation at refinance. Budget roof replacement in BRRRR light rehab if roof is 15+ years — the insurance savings justify the cost over 5 years of ownership.','high',ARRAY['brrrr','insurance','roof','florida']),
('deal_outcome','Due diligence period optimization','Best practice from CCG operations: Start due diligence tasks in parallel on day 1, not sequentially. Order title, schedule inspector, call contractor within 24 hours of contract signing. Every task that waits = potential closing delay = risk of losing momentum with seller. Parallel execution saves 5-10 days in the DD period.','high',ARRAY['due_diligence','operations','timeline']),
('market_pattern','ARV accuracy by deal type','Urban AI ARV analysis is most accurate on: standard 3/2 SFR in established neighborhoods with recent comparable sales. Least accurate on: unique properties (pool homes where few pool comps), large homes over 2,200 sqft (fewer comparables), major street homes vs interior (location adjustment), very new flips where recent sales are all investor-to-investor.','high',ARRAY['arv','urban_ai','analysis']),
('negotiation_outcome','Walk frequency and deal quality correlation','Data from CCG decisions: deals where we walked away from wholesaler pressure resulted in 0 missed opportunities that turned into good deals. Wholesalers who said "another buyer is in" and we walked: in 9 of 10 cases the property came back to market or wholesaler followed up within 30 days. Discipline to walk has not cost CCG good deals.','high',ARRAY['negotiation','walking','discipline']),
('market_pattern','Concrete block premium in Tampa Bay market','Insurance data confirms: concrete block homes in Tampa Bay get insured for 8-15% less than frame homes of equal value. In 2024-2025 with insurance market stress: CBS is not preferred — it is REQUIRED by some carriers for reasonable premiums. This advantage compounds over hold period. CBS is worth $5,000-15,000 in purchase price premium over comparable frame for rental portfolio.','high',ARRAY['construction','cbs','insurance','florida']);

